// SIMULA EL PLC: publica SOLO proceso en papid.envasadora.<MACHINE_CODE>.
// La orden y el personal los carga el admin por POST /api/orden; aquí NO van.
//
// Por valvuladora se manda: peso, setpoint, columna, leds, bultos (contador
// del PLC) y, al completar un bulto, id_bulto y peso_bulto. El dashboard arma
// la tabla y cuenta los bultos/lotes de la orden a partir de esto.

const MACHINE_CODE = 'B2-A-silo-1';
const PESO_PRODUCTO = 20; // tope de llenado de la bola (= pesoProducto de la orden)
const SETPOINT_INI = 20;
const COLUMNA_INI = 5;
const PASO = 1;

function acota(v, min, max) { return Math.max(min, Math.min(max, v)); }

let e = flow.get('estado');
if (!e) {
    e = {
        machine_code: MACHINE_CODE,
        peso_producto: PESO_PRODUCTO,
        valvuladoras: [
            { peso: 0, setpoint: SETPOINT_INI, columna: COLUMNA_INI, leds: { paro: false, limpieza: false, ciclo: false }, bultos: 0 },
            { peso: 0, setpoint: SETPOINT_INI, columna: COLUMNA_INI, leds: { paro: false, limpieza: false, ciclo: false }, bultos: 0 },
            { peso: 0, setpoint: SETPOINT_INI, columna: COLUMNA_INI, leds: { paro: false, limpieza: false, ciclo: false }, bultos: 0 }
        ]
    };
}
e.valvuladoras.forEach(v => {
    if (!v.leds) v.leds = { paro: false, limpieza: false, ciclo: false };
    if (typeof v.bultos !== 'number') v.bultos = 0;
    delete v.id_bulto; delete v.peso_bulto; // solo viajan en el mensaje donde se completó
});

let editando = flow.get('editando') || 'setpoint';
const tope = e.peso_producto > 0 ? e.peso_producto : 0;

switch (msg.topic) {
    case 'init':
        e.valvuladoras.forEach(v => { v.peso = 0; v.bultos = 0; });
        break;

    case 'sim':
        e.valvuladoras.forEach(v => {
            if (tope <= 0) { v.peso = 0; return; }
            if (v.peso >= tope) {
                // Bulto completado: el PLC sube su contador y reporta id/peso.
                v.bultos += 1;
                v.id_bulto = 'B-' + String(v.bultos).padStart(5, '0');
                v.peso_bulto = Math.round((tope + (Math.random() - 0.5) * 0.1) * 100) / 100;
                v.peso = 0; // reinicia el ciclo de llenado
            } else {
                const inc = Math.max(0.3, tope / 15) + Math.random() * (tope / 30);
                v.peso = acota(v.peso + inc, 0, tope);
            }
            v.peso = Math.round(v.peso * 10) / 10;
        });
        break;

    case 'subir':
        e.valvuladoras.forEach(v => { v[editando] = acota((v[editando] || 0) + PASO, 0, 9999); });
        break;
    case 'bajar':
        e.valvuladoras.forEach(v => { v[editando] = acota((v[editando] || 0) - PASO, 0, 9999); });
        break;
    case 'toggle':
        editando = (editando === 'setpoint') ? 'columna' : 'setpoint';
        flow.set('editando', editando);
        break;

    case 'led:paro':
    case 'led:limpieza':
    case 'led:ciclo': {
        const cual = msg.topic.split(':')[1];
        const idx = (typeof msg.payload === 'number') ? msg.payload : null;
        if (idx !== null && e.valvuladoras[idx]) {
            e.valvuladoras[idx].leds[cual] = !e.valvuladoras[idx].leds[cual];
        } else {
            e.valvuladoras.forEach(v => { v.leds[cual] = !v.leds[cual]; });
        }
        break;
    }
}

flow.set('estado', e);
node.status({ fill: 'blue', shape: 'dot', text: 'editando: ' + editando });
msg.payload = e;
return msg;

const e = msg.payload;
if (!e || !Array.isArray(e.valvuladoras)) {
    node.warn('payload sin valvuladoras, no se publica');
    return null;
}
const code = e.machine_code || 'B2-A-silo-1';
msg.topic = 'papid.envasadora.' + code;
return msg;
